39	func (s *Store) deleteUserCache(ctx context.Context, userID int32, result *DeleteUserResult) {
40		s.userCache.Delete(ctx, userCacheKey(userID))
41		if result == nil {
42			return
43		}
44		for _, key := range result.UserSettingKeys {
45			s.userSettingCache.Delete(ctx, getUserSettingCacheKey(userID, key.String()))
46		}
47	}
